head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.removeAll();
};
scwin.checkactiveElement = function() {
    return WebSquare.wUnit.getDomById($p.id + "wq_uuid_3_input") == document.activeElement;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 removeAll() 버튼을 클릭한다.-Click the removeAll () button in your browser.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. autocomplete 안에 있는 데이터가 초기화된다.- The data in autocomplete is initialized.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_input').value == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 초기화 된 autocomplete 를 더블클릭한다.- Double-click the initialized autocomplete.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_input').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. edit 모드로 진입된다.- Enter edit mode.
    WebSquare.wUnit.addCommand("assert", "scwin.checkactiveElement()", "true");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "label": "1",
        "value": "1"
    }, {
        "label": "2",
        "value": "2"
    }];
    dataList1.setJSON(jsonData);
    //Function unitTest
    //Create by Truong.Luu
    //Create date 22-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
